    data_explorer_pr_assignments = PGMaterializedView(
                schema="data",
                signature="explorer_pr_assignments",
                definition="SELECT pr.pull_request_id,\n    pr.repo_id AS id,\n    pr.pr_created_at AS created,\n    pr.pr_closed_at AS closed,\n    pre.created_at AS assign_date,\n    pre.action AS assignment_action,\n    pre.cntrb_id AS assignee,\n    pre.node_id\n   FROM (data.pull_requests pr\n     LEFT JOIN data.pull_request_events pre ON (((pr.pull_request_id = pre.pull_request_id) AND ((pre.action)::text = ANY (ARRAY[('unassigned'::character varying)::text, ('assigned'::character varying)::text])))))",
                with_data=True
            )

